function submit(payload) {
  submitting = true;
  submitBtn.disabled = true;

  // 点击提交瞬间四项的实际填写值快照。本次房间固定按 payload（即点击时
  // 的配置）创建；响应到达时再读一次当前值与之逐项比较。
  var submittedValues = readFormValues();

  fetch('/api/rooms', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload)
  }).then(function (resp) {
    // 记录正文是否完整读出并解析为 JSON。状态码已收到（如 201）但正文
    // 为空、被截断或读取中断时，bodyOk 为 false：此时不能拿解析失败的
    // 空数据冒充创建结果（否则会显示“编号：undefined”）。
    return resp.json().then(function (data) {
      return { ok: resp.ok, status: resp.status, data: data, bodyOk: true };
    }, function () {
      return { ok: resp.ok, status: resp.status, data: null, bodyOk: false };
    });
  }).then(function (result) {
    if (result.ok && result.status === 201) {
      // 只有正文完整读出、能解析且带有非空编号，才算拿到本次创建结果。
      var createdId = result.bodyOk && result.data &&
        typeof result.data.id === 'string' && result.data.id !== ''
        ? result.data.id : null;

      if (createdId === null) {
        // 已收到 201 但创建结果未能确认：房间可能已经在服务端保存。
        // 不承诺创建失败、不显示成功编号、不凭空拼房间或猜编号，
        // 不自动重发本次提交，也不清空或改动房间列表；表单四项以页面
        // 当前实际填写为准整体保留（含等待期间的修改，不整理名称首尾
        // 空白、不补齐未填项），提醒用户先刷新页面核对列表再决定。
        showMessage('warn', '创建结果未能确认：服务已返回成功状态，但回应内容未能完整读取，' +
          '房间可能已经保存。请先刷新页面查看房间列表，确认是否已创建后，再决定是否重新提交。');
        return;
      }

      var okText = '房间已创建，编号：' + createdId;

      // 是否复位以页面当前实际填写值为准，与提交时快照逐项比较：
      // 四项全部一致（含等待期间改过又完整恢复）才恢复初始表单；
      // 任一项不同——哪怕只动了名称的首尾空白——都整体保留当前四项
      // 及其对应的人数选择状态，不能只留改过的项，也不能把其他项
      // 恢复成旧配置；内容没填完整同样原样保留、不自动补齐。
      var currentValues = readFormValues();
      var unchanged = currentValues.name === submittedValues.name &&
        currentValues.game === submittedValues.game &&
        currentValues.capacity === submittedValues.capacity &&
        currentValues.turnSeconds === submittedValues.turnSeconds;

      if (unchanged) {
        showMessage('ok', okText);
        resetForm();
      } else {
        // 本次房间已按提交时的配置创建并生成编号；表单中是等待期间
        // 继续填写、尚未提交的新配置，不会自动创建下一间房，完整保留
        // 供用户处理完成后直接再次提交。
        showMessage('ok', okText + '。表单中当前填写的内容尚未提交，不会自动创建房间；' +
          '如需创建下一间，可直接点击“创建房间”。');
      }
      return loadRooms();
    }
    // 创建失败（被服务拒绝）：不触碰表单，等待期间的最新填写原样保留，
    // 不回退到提交时的值，仅显示服务给出的原因。
    var reason = result.data && result.data.error ? result.data.error
               : ('创建失败（HTTP ' + result.status + '）');
    showMessage('error', reason);
  }).catch(function () {
    // 连接失败同样保留当时最新的填写内容。
    showMessage('error', '无法连接服务，请确认服务仍在运行后重试。');
  }).finally(function () {
    submitting = false;
    submitBtn.disabled = false;
  });
}

// 创建时间列的三种正常展示（对象/数组已由 buildRoomRow 统一判为异常，
// 不会进入这里）：
//   1. 能解析成有效日期的字符串：按浏览器本地时区显示
//      YYYY-MM-DD HH:mm:ss（带时区偏移的时间换算成实际对应的本地时刻，
//      不把原串里的时分当本地时间），悬浮提示保留接口返回的原始字符串；
//   2. 无法解析的非空字符串：原文直接显示在单元格中（textContent 保证
//      尖括号等字符只作为文字呈现），不替换为当前时间，不附悬浮说明；

