// 临时验证：201 已收到但正文被截断时的页面行为（验证后删除）。
import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { execFile, spawn } from 'node:child_process';
import { mkdtemp, writeFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { promisify } from 'node:util';
import puppeteer from 'puppeteer-core';

const repoRoot = import.meta.dirname;
const chromePath = process.env.CHROME_PATH || '/usr/bin/google-chrome';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

let serverBin;
let browser;

const SEED =
  '{"id":"seed-alpha","name":"晨间飞行棋","game":"ludo","capacity":4,"turnSeconds":30,' +
  '"status":"playing","visibility":"public","createdAt":"2026-01-01T08:00:00Z","note":"保留我"}';

before(async () => {
  const dir = await mkdtemp(path.join(tmpdir(), 'score-arena-uibin-'));
  serverBin = path.join(dir, 'score-arena');
  await promisify(execFile)('go', ['build', '-o', serverBin, '.'], { cwd: repoRoot });
  browser = await puppeteer.launch({
    executablePath: chromePath,
    headless: true,
    args: ['--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage'],
  });
});

after(async () => {
  if (browser) await browser.close();
  if (serverBin) await rm(path.dirname(serverBin), { recursive: true, force: true });
});

function startServer(t, dataDir) {
  const proc = spawn(serverBin,
    ['serve', '--host', '127.0.0.1', '--port', '0', '--data-dir', dataDir],
    { stdio: ['ignore', 'pipe', 'inherit'] });
  t.after(() => { proc.kill('SIGKILL'); });
  return new Promise((resolve, reject) => {
    let buf = '';
    const timer = setTimeout(() => reject(new Error('timeout')), 15000);
    proc.stdout.on('data', (c) => {
      buf += c.toString();
      const m = buf.match(/listening on (http:\/\/\S+)/);
      if (m) { clearTimeout(timer); resolve(m[1]); }
    });
    proc.on('exit', (code) => { clearTimeout(timer); reject(new Error('exit ' + code)); });
  });
}

test('201 正文被截断：提示未能确认、保留填写、列表不变、不自动重发', { timeout: 60000 }, async (t) => {
  const dataDir = await mkdtemp(path.join(tmpdir(), 'score-arena-uidata-'));
  t.after(() => rm(dataDir, { recursive: true, force: true }));
  await writeFile(path.join(dataDir, 'rooms.json'), '[\n' + SEED + '\n]\n');
  const baseURL = await startServer(t, dataDir);
  const page = await browser.newPage();
  t.after(() => page.close());
  await page.goto(baseURL, { waitUntil: 'load' });
  await page.waitForFunction(
    () => document.querySelectorAll('#list-area table tbody tr').length === 1,
    { timeout: 10000 });
  const initialListText = await page.evaluate(
    () => document.getElementById('list-area').textContent);

  // 拦截创建请求：先真正转发给服务（房间会保存），再把截断的 201 正文回给页面。
  let postCount = 0;
  let releaseResponse;
  const responseGate = new Promise((r) => { releaseResponse = r; });
  await page.setRequestInterception(true);
  page.on('request', async (req) => {
    if (req.method() === 'POST' && req.url().endsWith('/api/rooms')) {
      postCount++;
      const real = await fetch(baseURL + '/api/rooms', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: req.postData(),
      });
      const body = await real.text();
      assert.equal(real.status, 201);
      await responseGate;
      // 截断到一半，构成合法 201 + 不完整 JSON。
      req.respond({
        status: 201,
        headers: { 'Content-Type': 'application/json' },
        body: body.slice(0, Math.floor(body.length / 2)),
      });
      return;
    }
    req.continue();
  });

  await page.type('#name', '  周末 飞行棋 🎲 友谊赛  ');
  await page.select('#game', 'ludo');
  await page.waitForFunction(() => !document.getElementById('capacity').disabled, { timeout: 5000 });
  await page.select('#capacity', '4');
  await page.type('#turnSeconds', '60');
  await page.click('#submit');

  // 等待期间按钮不可用，且继续修改表单（应以最新值保留）。
  await page.waitForFunction(() => document.getElementById('submit').disabled, { timeout: 5000 });
  await page.click('#turnSeconds', { clickCount: 3 });
  await page.type('#turnSeconds', '45');
  await sleep(200);
  assert.equal(postCount, 1, '等待期间不得再次发出创建请求');
  releaseResponse();

  // 表单区域出现“未能确认”提示。
  await page.waitForFunction(
    () => document.getElementById('form-msg').classList.contains('warn'),
    { timeout: 10000 });
  const msg = await page.evaluate(() => {
    const el = document.getElementById('form-msg');
    return { className: el.className, text: el.textContent };
  });
  assert.ok(msg.text.includes('未能确认'), '应提示创建结果未能确认: ' + msg.text);
  assert.ok(msg.text.includes('可能已经保存'), '应提示房间可能已经保存: ' + msg.text);
  assert.ok(msg.text.includes('刷新页面'), '应提醒先刷新页面查看列表: ' + msg.text);
  assert.ok(!msg.text.includes('undefined'), '不得出现 undefined 编号');
  assert.ok(!msg.text.includes('房间已创建'), '不得显示成功文案');
  assert.ok(!msg.className.includes('ok'), '不得使用成功样式');

  // 表单以处理结束时页面上的实际填写为准保留（时间改为 45，名称不去首尾空白）。
  const form = await page.evaluate(() => ({
    name: document.getElementById('name').value,
    game: document.getElementById('game').value,
    capacity: document.getElementById('capacity').value,
    capacityDisabled: document.getElementById('capacity').disabled,
    turnSeconds: document.getElementById('turnSeconds').value,
    submitDisabled: document.getElementById('submit').disabled,
  }));
  assert.deepEqual(form, {
    name: '  周末 飞行棋 🎲 友谊赛  ',
    game: 'ludo',
    capacity: '4',
    capacityDisabled: false,
    turnSeconds: '45',
    submitDisabled: false,
  }, '表单应保留处理结束时的实际填写，按钮恢复可用');

  // 列表保留原先内容与次序，不变成空提示或加载失败。
  const listText = await page.evaluate(() => document.getElementById('list-area').textContent);
  assert.equal(listText, initialListText, '列表应保持原先展示内容');
  assert.ok(!listText.includes('还没有房间记录'), '不得清空为无记录提示');
  assert.ok(!listText.includes('加载失败'), '不得显示列表加载失败');

  // 页面没有自动重发。
  await sleep(500);
  assert.equal(postCount, 1, '不得自动重发本次提交');

  // 服务端确实已保存该房间（证明“可能已经保存”的提示方向正确）。
  const rooms = (await (await fetch(baseURL + '/api/rooms')).json()).rooms;
  assert.equal(rooms.length, 2);
  assert.equal(rooms[1].name, '周末 飞行棋 🎲 友谊赛');
  assert.equal(rooms[1].turnSeconds, 60, '服务端按提交时的 60 秒保存，不受等待期间修改影响');
});

